// Fresher assumes Boot 'replaced' Spring and re-wires a DataSource by hand,
// not realizing auto-configuration already built one from application.properties.
@Configuration
class DbConfig {
    @Bean
    DataSource dataSource() {                 // collides with the auto-configured one
        var ds = new HikariDataSource();
        ds.setJdbcUrl("jdbc:postgresql://localhost/orders");
        return ds;
    }
}
// Result: confusion about which DataSource wins, or surprising overrides.
