```java
// @Service / @Repository / @Transactional are FRAMEWORK annotations;
// Boot only auto-configures the DataSource + EntityManager around them.
@Service
class OrderService {
    private final OrderRepository repo;
    OrderService(OrderRepository repo) { this.repo = repo; } // @Autowired implied

    @Transactional                              // from spring-tx (framework)
    Order create(String item) { return repo.save(new Order(null, item)); }
}

@Repository
interface OrderRepository extends JpaRepository<Order, Long> {} // Spring Data

// application.properties supplies the DataSource — Boot builds it. No DbConfig needed.
```

